import os
import xml.etree.ElementTree as ET

BASE_DIR = "/root/awesome_unpacked"
SLIDES_DIR = os.path.join(BASE_DIR, "ppt", "slides")

NS = {
    "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
    "ep": "http://schemas.openxmlformats.org/officeDocument/2006/extended-properties",
}
for prefix, uri in NS.items():
    ET.register_namespace(prefix if prefix != "ep" else "ns0", uri)

# Count words and paragraphs
words = 0
paragraphs = 0
slide_ns = {
    "p": "http://schemas.openxmlformats.org/presentationml/2006/main",
    "a": NS["a"],
}
for filename in sorted(os.listdir(SLIDES_DIR)):
    if not filename.startswith("slide") or not filename.endswith(".xml"):
        continue
    slide_tree = ET.parse(os.path.join(SLIDES_DIR, filename))
    slide_root = slide_tree.getroot()
    for p in slide_root.findall(".//a:p", slide_ns):
        texts = [t.text for t in p.findall(".//a:t", slide_ns) if t.text]
        if not texts:
            continue
        joined = " ".join(texts)
        if joined.strip():
            paragraphs += 1
            words += len(joined.split())

app_path = os.path.join(BASE_DIR, "docProps", "app.xml")
app_tree = ET.parse(app_path)
app_root = app_tree.getroot()

for elem in app_root.findall(".//ep:Slides", NS):
    elem.text = "7"
for elem in app_root.findall(".//ep:Paragraphs", NS):
    elem.text = str(paragraphs)
for elem in app_root.findall(".//ep:Words", NS):
    elem.text = str(words)

app_tree.write(app_path, encoding="ascii", xml_declaration=True)
